nTestCases = int(input())
for testCase in range(nTestCases):
	(N, X, Y) = map(int, input().split())
	citiesSadness = list(map(int, input().split()))
	maxSadness = max(citiesSadness)
	nBlimps = 0
	if Y >= X:
		if maxSadness % Y == 0:
			nBlimps = maxSadness / Y
		else:
			nBlimps = int(maxSadness / Y) + 1
	else:
		for targetCity in range(len(citiesSadness) - 1, -1, -1):
			if citiesSadness[targetCity] > 0:
				iterations = int(citiesSadness[targetCity] / X) + (citiesSadness[targetCity] % X > 0)
				citiesSadness = [citySadness - Y * iterations for citySadness in citiesSadness[:targetCity]] + [citiesSadness[targetCity] - X * iterations] + citiesSadness[targetCity + 1:]
				nBlimps += iterations
	print(nBlimps)
